{
  "name": "@zhzy0077/opencode-terminal-title",
  "version": "0.1.0",
  "description": "Terminal title plugin for OpenCode - updates terminal window title based on session state",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "README.md"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": "^0.x"
  },
  "devDependencies": {
    "@types/node": "^25.5.0",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "terminal",
    "title"
  ],
  "author": "zhzy0077",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/zhzy0077/opencode-terminal-title.git"
  },
  "bugs": {
    "url": "https://github.com/zhzy0077/opencode-terminal-title/issues"
  },
  "homepage": "https://github.com/zhzy0077/opencode-terminal-title#readme"
}

const ICONS = {
    busy: "[*]",
    idle: "[✓]",
    error: "[✗]",
    permission: "[?]",
};
const STATUS_TEXT = {
    busy: "Working",
    idle: "Done",
    error: "Error",
    permission: "Waiting",
};
const sessions = new Map();
function truncate(str, max) {
    return str.length > max ? str.slice(0, max - 3) + "..." : str;
}
function setTitle(state) {
    const icon = ICONS[state.status];
    const text = STATUS_TEXT[state.status];
    const title = truncate(state.title, 40);
    const titleString = `${icon} ${text} | ${title}`;
    process.stdout.write(`\x1b]0;${titleString}\x07`);
}
export default async function (_input) {
    return {
        event: async ({ event }) => {
            const type = event.type;
            const props = event.properties;
            switch (type) {
                // Session lifecycle
                case "session.created":
                case "session.updated": {
                    const info = props.info;
                    const id = info.id;
                    const existing = sessions.get(id);
                    sessions.set(id, {
                        title: info.title,
                        status: existing?.status ?? "idle",
                    });
                    if (existing) {
                        setTitle(existing);
                    }
                    break;
                }
                case "session.deleted": {
                    const info = props.info;
                    sessions.delete(info.id);
                    break;
                }
                // Session status - primary source of truth
                // @ts-expect-error session.status not in SDK types yet
                case "session.status": {
                    const { sessionID, status } = props;
                    let session = sessions.get(sessionID);
                    if (!session) {
                        // Create new session
                        const newStatus = status.type === "idle" ? "idle" : "busy";
                        session = {
                            title: `Session ${sessionID.slice(0, 8)}`,
                            status: newStatus,
                        };
                        sessions.set(sessionID, session);
                        setTitle(session);
                        break;
                    }
                    // Don't override permission status with busy
                    if (session.status === "permission") {
                        if (status.type === "idle") {
                            session.status = "idle";
                            setTitle(session);
                        }
                        break;
                    }
                    if (status.type === "idle") {
                        session.status = "idle";
                    }
                    else if (status.type === "busy" || status.type === "retry") {
                        session.status = "busy";
                    }
                    setTitle(session);
                    break;
                }
                // Legacy session.idle event
                case "session.idle": {
                    const sessionID = props.sessionID;
                    const session = sessions.get(sessionID);
                    if (!session)
                        return;
                    session.status = "idle";
                    setTitle(session);
                    break;
                }
                // Error handling
                case "session.error": {
                    const sessionID = props.sessionID;
                    if (!sessionID)
                        return;
                    const session = sessions.get(sessionID);
                    if (!session)
                        return;
                    session.status = "error";
                    setTitle(session);
                    break;
                }
                // Permission handling
                // @ts-expect-error permission.asked not in SDK types yet
                case "permission.asked":
                case "permission.updated": {
                    const perm = props;
                    let session = sessions.get(perm.sessionID);
                    if (!session) {
                        session = {
                            title: `Session ${perm.sessionID.slice(0, 8)}`,
                            status: "permission",
                        };
                        sessions.set(perm.sessionID, session);
                    }
                    else {
                        session.status = "permission";
                    }
                    setTitle(session);
                    break;
                }
                case "permission.replied": {
                    const perm = props;
                    const session = sessions.get(perm.sessionID);
                    if (!session)
                        return;
                    session.status = "busy";
                    setTitle(session);
                    break;
                }
                default:
                    // Ignore other events
                    break;
            }
        },
    };
}
